const listDiscoverFeed = `-- name: ListDiscoverFeed :many


WITH me AS (
  SELECT NOT EXISTS (SELECT 1 FROM social_settings s WHERE s.user_id = $3::uuid AND NOT s.profiling_enabled) AS profiling
), cand AS (
  SELECT e.id AS event_id, e.starts_at
  FROM events e
  WHERE e.discoverable AND e.deleted_at IS NULL
    AND e.starts_at < $4::timestamptz AND e.ends_at > $5::timestamptz
    AND discover_event_visible($3::uuid, e.id, $5::timestamptz)
), vis AS (
  SELECT r.event_id, r.user_id AS friend_id,
         CASE WHEN me.profiling
                   AND NOT EXISTS (SELECT 1 FROM social_settings s WHERE s.user_id = r.user_id AND NOT s.profiling_enabled)
              THEN COALESCE(fs.score, 0) ELSE 0 END::float8 AS score
  FROM cand
  CROSS JOIN me
  JOIN event_rsvps r ON r.event_id = cand.event_id AND (r.status = 'going' OR r.attendance = 'attended')
  JOIN friendships f ON f.user_low_id = LEAST($3::uuid, r.user_id) AND f.user_high_id = GREATEST($3::uuid, r.user_id)
                    AND f.status = 'accepted'
  LEFT JOIN friend_scores fs ON fs.user_low_id = f.user_low_id AND fs.user_high_id = f.user_high_id
  WHERE discover_friend_visible($3::uuid, r.user_id, r.event_id, $5::timestamptz)
), ranked AS (
  SELECT cand.event_id, count(vis.friend_id) AS n,
         row_number() OVER (ORDER BY COALESCE(sum(vis.score), 0) DESC, count(vis.friend_id) DESC,
                                     cand.starts_at, cand.event_id) AS pos
  FROM cand
  LEFT JOIN vis ON vis.event_id = cand.event_id
  GROUP BY cand.event_id, cand.starts_at
)
SELECT e.id AS event_id, e.type, e.title, e.starts_at, e.ends_at, e.city AS event_city, e.district AS event_district,
       t.id AS tayfa_id, t.name AS tayfa_name, t.description AS tayfa_description, t.city AS tayfa_city,
       t.created_at AS tayfa_created_at, t.stats_showcase AS tayfa_stats_showcase,
       ranked.n::integer AS friend_count,
       (SELECT count(*) FROM events x
        WHERE x.tayfa_id = t.id AND x.deleted_at IS NULL AND x.status <> 'cancelled'
          AND x.ends_at <= $1::timestamptz)::integer AS event_count,
       (SELECT count(*) FROM event_rsvps a JOIN events x ON x.id = a.event_id
        WHERE x.tayfa_id = t.id AND x.deleted_at IS NULL AND x.status <> 'cancelled'
          AND x.ends_at <= $1::timestamptz AND a.attendance = 'attended')::integer AS attendance_count,
       (SELECT COALESCE(jsonb_agg(jsonb_build_object('user_id', b.friend_id, 'display_name', b.display_name,
                                                     'avatar_upload_id', b.avatar_upload_id)
                                  ORDER BY b.score DESC, b.display_name, b.friend_id), '[]'::jsonb)
        FROM (SELECT v.friend_id, v.score, p.display_name, p.avatar_upload_id
              FROM vis v JOIN user_profiles p ON p.user_id = v.friend_id
              WHERE v.event_id = e.id
              ORDER BY v.score DESC, p.display_name, v.friend_id
              LIMIT 3) b)::jsonb AS friends
FROM ranked
JOIN events e ON e.id = ranked.event_id
JOIN tayfas t ON t.id = e.tayfa_id
WHERE ranked.pos <= $2::bigint
ORDER BY ranked.pos
`

type ListDiscoverFeedParams struct {
	FrozenBefore pgtype.Timestamptz
	N            int64
	Viewer       pgtype.UUID
	Until        pgtype.Timestamptz
	Now          pgtype.Timestamptz
}

type ListDiscoverFeedRow struct {
	EventID            pgtype.UUID
	Type               string
	Title              string
	StartsAt           pgtype.Timestamptz
	EndsAt             pgtype.Timestamptz
	EventCity          pgtype.Text
	EventDistrict      pgtype.Text
	TayfaID            pgtype.UUID
	TayfaName          string
	TayfaDescription   pgtype.Text
	TayfaCity          pgtype.Text
	TayfaCreatedAt     pgtype.Timestamptz
	TayfaStatsShowcase bool
	FriendCount        int32
	EventCount         int32
	AttendanceCount    int32
	Friends            []byte
}

// Keşfet (issue #210, ADR-0033; herkese açık: issue #227, ADR-0035).
// Listelenebilirlik tayfa_discover_listable (00028), etkinliğin izleyiciye
// görünmesi discover_event_visible ve "görünür arkadaş"
// discover_friend_visible (00029) ile tek yerde tanımlıdır. Arkadaşlık
// puanı yalnızca sıralamada kullanılır; hiçbir sorgunun sonucunda yoktur.
// ---------------------------------------------------------------------------
// Akış
// En iyi n etkinlik (Keşfet herkese açık, issue #227, ADR-0035): izleyiciye
// görünen bütün uygun etkinlikler (discover_event_visible); arkadaşı
// olmayan da listelenir. Sıra: görünür arkadaşlarla puan toplamı, görünür
// arkadaş sayısı, başlangıç, kimlik; arkadaşı olmayanlar yalnızca başlangıç
// ve kimlikle sıralanır. Tayfa olguları donmuş etkinliklerden (bitişten 7
// gün geçmiş, iptal edilmemiş, silinmemiş; ADR-0026 §1). En çok 3 arkadaş
// (puan, sonra ad sırasıyla); arkadaş yoksa boş liste ve 0. Puan dönmez.
func (q *Queries) ListDiscoverFeed(ctx context.Context, arg ListDiscoverFeedParams) ([]ListDiscoverFeedRow, error) {
	rows, err := q.db.Query(ctx, listDiscoverFeed,
		arg.FrozenBefore,
		arg.N,
		arg.Viewer,
		arg.Until,
		arg.Now,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListDiscoverFeedRow{}
	for rows.Next() {
		var i ListDiscoverFeedRow
		if err := rows.Scan(
			&i.EventID,
			&i.Type,
			&i.Title,
			&i.StartsAt,
			&i.EndsAt,
			&i.EventCity,
			&i.EventDistrict,
			&i.TayfaID,
			&i.TayfaName,
			&i.TayfaDescription,
			&i.TayfaCity,
			&i.TayfaCreatedAt,
			&i.TayfaStatsShowcase,
			&i.FriendCount,
			&i.EventCount,
			&i.AttendanceCount,
			&i.Friends,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listSafetyShares = `-- name: ListSafetyShares :many
SELECT c.user_id, p.display_name, p.avatar_upload_id,
       e.starts_at, e.ends_at, c.grace_minutes, c.returned_at, c.alert_sent_at
FROM event_safety_contacts c
JOIN events e ON e.id = c.event_id
JOIN tayfas t ON t.id = e.tayfa_id
LEFT JOIN user_profiles p ON p.user_id = c.user_id AND p.deleted_at IS NULL
JOIN memberships m ON m.tayfa_id = e.tayfa_id AND m.user_id = c.user_id AND m.status = 'active'
JOIN event_rsvps r ON r.event_id = c.event_id AND r.user_id = c.user_id
WHERE c.contact_user_id = $1
  AND (e.ends_at > $2::timestamptz
       OR c.alert_sent_at > $3::timestamptz)
  AND t.deleted_at IS NULL AND t.deletion_requested_at IS NULL AND t.suspended_at IS NULL
  AND ((r.status = 'going' AND e.status = 'scheduled' AND e.deleted_at IS NULL)
       OR (c.alert_sent_at IS NOT NULL AND r.checked_in_at IS NOT NULL))
  AND EXISTS (SELECT 1 FROM friendships f
              WHERE f.user_low_id = LEAST(c.user_id, c.contact_user_id)
                AND f.user_high_id = GREATEST(c.user_id, c.contact_user_id)
                AND f.status = 'accepted')
  AND NOT EXISTS (SELECT 1 FROM user_blocks ub
                  WHERE (ub.blocker_id = c.user_id AND ub.blocked_id = c.contact_user_id)
                     OR (ub.blocker_id = c.contact_user_id AND ub.blocked_id = c.user_id))
ORDER BY e.starts_at DESC, e.id
LIMIT 50
`

type ListSafetySharesParams struct {
	ContactID    pgtype.UUID
	EndedAfter   pgtype.Timestamptz
	AlertedAfter pgtype.Timestamptz
}

type ListSafetySharesRow struct {
	UserID         pgtype.UUID
	DisplayName    pgtype.Text
	AvatarUploadID pgtype.UUID
	StartsAt       pgtype.Timestamptz
	EndsAt         pgtype.Timestamptz
	GraceMinutes   int32
	ReturnedAt     pgtype.Timestamptz
	AlertSentAt    pgtype.Timestamptz
}

// Kişiyi güvenlik kişisi seçenlerin etkinlikleri: bitişinden 24 saat
// geçmemiş ya da alarmı son 7 günde gitmiş. Yalnızca kim, saat aralığı ve
// durum (platform sahibi, 2026-11-16): tayfa adı, etkinlik başlığı ve
// kimliği, buluşma yeri ve il/ilçe seçilmez. Paylaşım
// yalnızca hâlâ geçerliyse görünür: ikisi arkadaş, engel yok, katılımcı
// tayfanın aktif üyesi ve etkinliğe going; etkinlik silinmemiş ya da
// iptal edilmemiş, tayfa silinmemiş ya da askıda değil. Alarm gitmişse
// (etkinlik sonradan iptal ya da silinmiş olsa bile) katılımcı check-in
// yaptıysa görünür; alarmın kendisi bildirimle gitti.
func (q *Queries) ListSafetyShares(ctx context.Context, arg ListSafetySharesParams) ([]ListSafetySharesRow, error) {
	rows, err := q.db.Query(ctx, listSafetyShares, arg.ContactID, arg.EndedAfter, arg.AlertedAfter)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListSafetySharesRow{}
	for rows.Next() {
		var i ListSafetySharesRow
		if err := rows.Scan(
			&i.UserID,
			&i.DisplayName,
			&i.AvatarUploadID,
			&i.StartsAt,
			&i.EndsAt,
			&i.GraceMinutes,
			&i.ReturnedAt,
			&i.AlertSentAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockDueSafetyAlerts = `-- name: LockDueSafetyAlerts :many

SELECT c.event_id, c.user_id, c.contact_user_id
FROM event_safety_contacts c
JOIN events e ON e.id = c.event_id
JOIN memberships m ON m.tayfa_id = e.tayfa_id AND m.user_id = c.user_id AND m.status = 'active'
JOIN event_rsvps r ON r.event_id = c.event_id AND r.user_id = c.user_id
WHERE c.returned_at IS NULL AND c.alert_sent_at IS NULL
  AND e.ends_at + make_interval(mins => c.grace_minutes) <= $1::timestamptz
  AND ((r.status = 'going' AND e.status = 'scheduled' AND e.deleted_at IS NULL)
       OR r.checked_in_at IS NOT NULL)
  AND EXISTS (SELECT 1 FROM friendships f
              WHERE f.user_low_id = LEAST(c.user_id, c.contact_user_id)
                AND f.user_high_id = GREATEST(c.user_id, c.contact_user_id)
                AND f.status = 'accepted')
  AND NOT EXISTS (SELECT 1 FROM user_blocks ub
                  WHERE (ub.blocker_id = c.user_id AND ub.blocked_id = c.contact_user_id)
                     OR (ub.blocker_id = c.contact_user_id AND ub.blocked_id = c.user_id))
ORDER BY e.ends_at, c.event_id, c.user_id
LIMIT $2
FOR UPDATE OF c SKIP LOCKED
`

type LockDueSafetyAlertsParams struct {
	Now pgtype.Timestamptz
	N   int32
}

type LockDueSafetyAlertsRow struct {
	EventID       pgtype.UUID
	UserID        pgtype.UUID
	ContactUserID pgtype.UUID
}

// ---------------------------------------------------------------------------
// safety-alerts işi
// Alarmı gelmiş satırlar: döndüm yok, alarm gitmemiş, bitiş + tolerans
// geçmiş; katılımcı tayfanın aktif üyesi. Planlı ve silinmemiş etkinlikte
// going olmalı; etkinlik iptal ya da silindiyse yalnızca check-in
// yapılmışsa (yola çıkmış demektir). Gönderim anında ikisi hâlâ arkadaş ve
// engel yok.
func (q *Queries) LockDueSafetyAlerts(ctx context.Context, arg LockDueSafetyAlertsParams) ([]LockDueSafetyAlertsRow, error) {
	rows, err := q.db.Query(ctx, lockDueSafetyAlerts, arg.Now, arg.N)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LockDueSafetyAlertsRow{}
	for rows.Next() {
		var i LockDueSafetyAlertsRow
		if err := rows.Scan(&i.EventID, &i.UserID, &i.ContactUserID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

