const requestTayfaDiscover = `-- name: RequestTayfaDiscover :exec
INSERT INTO tayfa_discover (tayfa_id, status, requested_at, requested_by, status_changed_at)
VALUES ($1, 'pending', $2, $3, $2)
ON CONFLICT (tayfa_id) DO UPDATE
SET status = 'pending', requested_at = EXCLUDED.requested_at, requested_by = EXCLUDED.requested_by,
    status_changed_at = EXCLUDED.status_changed_at
WHERE tayfa_discover.status = 'rejected'
`

type RequestTayfaDiscoverParams struct {
	TayfaID     pgtype.UUID
	Now         pgtype.Timestamptz
	RequestedBy pgtype.UUID
}

// Açılışta başvuru: satır yoksa pending açılır; reddedilmişse yeniden
// pending olur. Onaylı, bekleyen ve düşürülmüş başvuru değişmez.
func (q *Queries) RequestTayfaDiscover(ctx context.Context, arg RequestTayfaDiscoverParams) error {
	_, err := q.db.Exec(ctx, requestTayfaDiscover, arg.TayfaID, arg.Now, arg.RequestedBy)
	return err
}

const safetyContactAllowed = `-- name: SafetyContactAllowed :one
SELECT EXISTS (
  SELECT 1 FROM friendships f
  WHERE f.user_low_id = LEAST($1::uuid, $2::uuid)
    AND f.user_high_id = GREATEST($1::uuid, $2::uuid)
    AND f.status = 'accepted'
) AND NOT EXISTS (
  SELECT 1 FROM user_blocks ub
  WHERE (ub.blocker_id = $1::uuid AND ub.blocked_id = $2::uuid)
     OR (ub.blocker_id = $2::uuid AND ub.blocked_id = $1::uuid)
) AND NOT EXISTS (
  SELECT 1 FROM user_profiles p WHERE p.user_id = $2::uuid AND p.deleted_at IS NOT NULL
) AND NOT EXISTS (
  SELECT 1 FROM user_platform_bans b WHERE b.user_id = $2::uuid AND b.banned_at IS NOT NULL
)
`

type SafetyContactAllowedParams struct {
	UserID    pgtype.UUID
	ContactID pgtype.UUID
}

// Kişi güvenlik kişisi olabilir mi: kabul edilmiş arkadaş, iki yönden engel
// yok, hesap silinmemiş ve platformda banlı değil.
func (q *Queries) SafetyContactAllowed(ctx context.Context, arg SafetyContactAllowedParams) (pgtype.Bool, error) {
	row := q.db.QueryRow(ctx, safetyContactAllowed, arg.UserID, arg.ContactID)
	var column_1 pgtype.Bool
	err := row.Scan(&column_1)
	return column_1, err
}

